+function violationsFromSnapshot(raw) {
+    if (!raw || !String(raw).trim()) return [];
+    var parsed = JSON.parse(raw);
+    var violations = (parsed && parsed.violations) ? parsed.violations : (Array.isArray(parsed) ? parsed : []);
