 */
function jscpdEntryOf(line) {
    var m = line.match(/^\s*(?:[-*]\s*)?(.+?):\s*(\d+)-(\d+)\s*$/);
    return m ? { path: m[1], start: m[2], end: m[3] } : null;
}

