        assert.equal(items[1].rule, 'unused_import');
        assert.equal(items[1].path, 'lib/utils/legacy.dart');
        assert.equal(items[2].rule, 'blank_line_check');
    });
});

suite('ciViolations.extractViolations — dart test shape (UT-5)', function() {

