    ticketKey: ticketKey,
    workingDir: config.workingDir || null,
    responseText: fixSummary,
    resolutions: lapResolutions,
    auditNoCodeChange: lapGate.auditResolve,
    runUrl: reworkRunUrl()
});
console.log('Thread replies posted:', repliesPosted);

